//! ATDD red-phase scaffolds for story 2 — container pane's agent avatar and cwd.
//!
//! Generated by the `bmad-testarch-atdd` workflow (see
//! `_bmad-output/test-artifacts/atdd-checklist-2-container-sidebar-agent-cwd.md`).
//! Rust has no `test.skip()`: `#[ignore = "ATDD RED: …"]` was the red-phase
//! marker (with the criterion id in the reason) until each leaf went green.
//!
//! These live beside the sidebar rather than in `tests/` because AC-2 reads the
//! hover card's own `SidebarInfo`, which is private to this module. They add no
//! production code.
//!
//! AC-1, AC-3 and AC-4 are characterisation pins: story 1's transport already
//! makes the in-container daemon the source of the agent and cwd, so those
//! scaffolds passed before this story. AC-2 is the genuinely red one — a
//! container row had no machine line until this story added it. The two
//! `ac2_*` companions below pin that the new fallback changed no other row.

use super::*;
use crate::core::cli_agent::{AgentSessionState, AgentStatus, CLIAgent};
use crate::core::session::{RemoteTarget, WorkspaceId};
use crate::daemon::protocol::DaemonMsg;
use crate::terminal::{PaneRoute, PaneWorkspace};
use crate::ui::app::test_window::harness_with_tabs;
use crate::ui::remote_connect::HostLinks;
use gpui::TestAppContext;
use std::io::Write as _;
use std::time::Duration;

/// Put tab `i` on a container workspace, the way opening a container pane
/// does. The workspace target is what gives the pane its host id and route.
fn attach_container(app: &Tty7App, i: usize, name: &str, cx: &mut gpui::App) {
    let slot = app.tabs[i]
        .pane
        .first_leaf()
        .expect("harness tab has a pane");
    let leaf = slot.terminal().expect("harness pane is a terminal");
    leaf.update(cx, |view, _| {
        view.set_workspace(Some(PaneWorkspace {
            workspace: WorkspaceId::new(),
            target: RemoteTarget::Container {
                container: name.to_string(),
            },
            spec: None,
            label: Some(name.to_string()),
            resize_echo: false,
            size_lease: false,
        }));
    });
}

/// The directory the first tab's pane is tracking, read the way the sidebar
/// reads it.
fn pane_cwd(app: &Tty7App, cx: &gpui::App) -> Option<std::path::PathBuf> {
    let slot = app.tabs[0].pane.first_leaf()?;
    let leaf = slot.terminal()?;
    leaf.read(cx).effective_cwd()
}

/// Wait for the daemon-side report to reach the pane. The reader thread feeds
/// the state, so this is a poll rather than a render.
fn poll_until<T: PartialEq>(want: &T, probe: impl Fn() -> Option<T>) -> Option<T> {
    let mut last = None;
    for _ in 0..200 {
        last = probe();
        if last.as_ref() == Some(want) {
            return last;
        }
        std::thread::sleep(Duration::from_millis(5));
    }
    last
}

#[gpui::test]
fn ac1_the_sidebar_pairs_the_in_container_agent_with_its_status(cx: &mut TestAppContext) {
    let (app, mut vcx, mut streams) = harness_with_tabs(cx, 1);
    app.update(&mut vcx, |app, cx| attach_container(app, 0, "web", cx));

    // The host side only ever ran `docker exec … tty7-server --stdio`; nothing
    // in this process names an agent. Everything below arrives from the daemon
    // inside the container.
    let mut daemon_side = streams.remove(0);
    DaemonMsg::Agent(Some(CLIAgent::Claude))
        .encode(&mut daemon_side)
        .unwrap();
    DaemonMsg::AgentStatus(Some(AgentSessionState {
        status: AgentStatus::Working,
        ..Default::default()
    }))
    .encode(&mut daemon_side)
    .unwrap();
    daemon_side.flush().unwrap();

    let got = poll_until(&(CLIAgent::Claude, AgentStatus::Working), || {
        app.read_with(&vcx, |app, cx| app.tabs[0].agent_row(cx))
    });
    assert_eq!(
        got,
        Some((CLIAgent::Claude, AgentStatus::Working)),
        "the row must take the agent and its working dot from inside the container"
    );
}

#[gpui::test]
fn ac2_a_container_row_names_its_container_in_the_hover_card(cx: &mut TestAppContext) {
    let (app, mut vcx, _streams) = harness_with_tabs(cx, 1);
    app.update(&mut vcx, |app, cx| attach_container(app, 0, "web", cx));

    let info = app.update_in(&mut vcx, |app, window, cx| {
        app.sidebar_info(
            &app.tabs[0],
            window,
            cx,
            &SidebarRowShown {
                title: None,
                branch: None,
                cwd: None,
            },
        )
    });
    let info = info.expect("the card has a line to draw");
    assert_eq!(
        info.host.as_deref(),
        Some("container web"),
        "a container row's card must name the container it lives in"
    );
}

