/// A shell that ssh'd onward already names its machine; the workspace fallback
/// must leave that answer alone.
#[gpui::test]
fn ac2_a_shell_that_sshd_onward_keeps_its_own_target(cx: &mut TestAppContext) {
    use crate::daemon::protocol::{RemoteContext, RemoteKind};

    let (app, mut vcx, mut streams) = harness_with_tabs(cx, 1);
    let mut daemon_side = streams.remove(0);
    DaemonMsg::RemoteContext(Some(RemoteContext {
        kind: RemoteKind::Ssh,
        argv: vec!["ssh".into(), "ubuntu@alpha".into()],
        target: "ubuntu@alpha".into(),
    }))
    .encode(&mut daemon_side)
    .unwrap();
    daemon_side.flush().unwrap();

    let want = "ubuntu@alpha".to_string();
    let seen = poll_until(&want, || {
        app.read_with(&vcx, |app, cx| {
            app.tabs[0]
                .pane
                .first_leaf()?
                .terminal()?
                .read(cx)
                .remote_context()
                .map(|r| r.target)
        })
    });
    assert_eq!(seen, Some(want), "the shell's own report must land");

    let info = app.update_in(&mut vcx, |app, window, cx| {
        app.sidebar_info(
            &app.tabs[0],
            window,
            cx,
            &SidebarRowShown {
                title: None,
                branch: None,
                cwd: None,
            },
        )
    });
    assert_eq!(
        info.expect("a remote shell is a line to draw")
            .host
            .as_deref(),
        Some("ubuntu@alpha"),
        "an SSH row keeps naming its own target"
    );
}

