/// A container pane whose shell ssh'd onward is on a third machine; that
/// shell's report outranks the workspace target, exactly as for a local pane.
#[gpui::test]
fn ac2_a_container_shell_that_sshd_onward_names_the_further_machine(cx: &mut TestAppContext) {
    use crate::daemon::protocol::{RemoteContext, RemoteKind};

    let (app, mut vcx, mut streams) = harness_with_tabs(cx, 1);
    app.update(&mut vcx, |app, cx| attach_container(app, 0, "web", cx));

    let mut daemon_side = streams.remove(0);
    DaemonMsg::RemoteContext(Some(RemoteContext {
        kind: RemoteKind::Ssh,
        argv: vec!["ssh".into(), "ubuntu@alpha".into()],
        target: "ubuntu@alpha".into(),
    }))
    .encode(&mut daemon_side)
    .unwrap();
    daemon_side.flush().unwrap();

    let want = "ubuntu@alpha".to_string();
    let seen = poll_until(&want, || {
        app.read_with(&vcx, |app, cx| {
            app.tabs[0]
                .pane
                .first_leaf()?
                .terminal()?
                .read(cx)
                .remote_context()
                .map(|r| r.target)
        })
    });
    assert_eq!(seen, Some(want), "the shell's onward hop must land");

    let info = app.update_in(&mut vcx, |app, window, cx| {
        app.sidebar_info(
            &app.tabs[0],
            window,
            cx,
            &SidebarRowShown {
                title: None,
                branch: None,
                cwd: None,
            },
        )
    });
    assert_eq!(
        info.expect("a farther machine is a line to draw")
            .host
            .as_deref(),
        Some("ubuntu@alpha"),
        "the shell's own report wins over the workspace's container"
    );
}

/// Every non-container workspace target keeps the card's old answer: no
/// machine line. Only `Container` may fall back to the workspace target, so an
/// SSH, WSL, local-stdio, profile, or alias row stays byte-identical.
#[gpui::test]
fn ac2_only_a_container_workspace_gets_a_machine_line(cx: &mut TestAppContext) {
    let targets = [
        RemoteTarget::Profile {
            id: uuid::Uuid::new_v4(),
        },
        RemoteTarget::Alias {
            alias: "devbox".into(),
        },
        RemoteTarget::Direct {
            user: "me".into(),
            host: "build-box".into(),
            port: 22,
        },
        RemoteTarget::Wsl {
            distro: "Ubuntu-22.04".into(),
        },
        RemoteTarget::LocalStdio {
            program: "/usr/bin/tty7-server".into(),
            args: vec!["--stdio".into()],
        },
    ];
    let (app, mut vcx, _streams) = harness_with_tabs(cx, targets.len());

    for (i, target) in targets.into_iter().enumerate() {
        let name = target.to_string();
        app.update(&mut vcx, |app, cx| {
            let slot = app.tabs[i]
                .pane
                .first_leaf()
                .expect("harness tab has a pane");
            let leaf = slot.terminal().expect("harness pane is a terminal");
            let label = name.clone();
            leaf.update(cx, |view, _| {
                view.set_workspace(Some(PaneWorkspace {
                    workspace: WorkspaceId::new(),
                    target,
                    spec: None,
                    label: Some(label),
                    resize_echo: false,
                    size_lease: false,
                }));
            });
            assert_eq!(
                leaf.read(cx).machine_label(),
                None,
                "{name} must not earn a machine label from its workspace"
            );
        });

        let info = app.update_in(&mut vcx, |app, window, cx| {
            app.sidebar_info(
                &app.tabs[i],
                window,
                cx,
                &SidebarRowShown {
                    title: None,
                    branch: None,
                    cwd: None,
                },
            )
        });
        assert!(
            info.and_then(|i| i.host).is_none(),
            "{name} must not gain a host line in the card"
        );
    }
}

#[gpui::test]
fn ac3_container_cwd_is_what_the_shell_reported_and_shortens_against_the_container_home(
    cx: &mut TestAppContext,
) {
    use std::path::PathBuf;

    let (app, mut vcx, mut streams) = harness_with_tabs(cx, 1);
    app.update(&mut vcx, |app, cx| attach_container(app, 0, "web", cx));

    let mut daemon_side = streams.remove(0);
    DaemonMsg::Cwd(PathBuf::from("/workspace/app"))
        .encode(&mut daemon_side)
        .unwrap();
    daemon_side.flush().unwrap();

    let want = PathBuf::from("/workspace/app");
    let cwd = poll_until(&want, || app.read_with(&vcx, |app, cx| pane_cwd(app, cx)));
    assert_eq!(
        cwd,
        Some(want),
        "the row must read the directory the container shell reported"
    );

    // `~` is the container's home, never this machine's. With no link up the
    // container's home is unknown, and the pane says so rather than falling
    // back to this laptop's `$HOME`.
    let home = app.read_with(&vcx, |app, cx| {
        app.tabs[0]
            .pane
            .first_leaf()?
            .terminal()?
            .read(cx)
            .display_home(cx)
    });
    assert_eq!(
        home, None,
        "a container pane's `~` is its host's home, never this machine's"
    );

    // Once the container link is up, `HostLinks` holds the home the container
    // reported. The row passes exactly that home to the one `~` formatter.
    let host = app.read_with(&vcx, |app, cx| {
        let slot = app.tabs[0]
            .pane
            .first_leaf()
            .expect("harness tab has a pane");
        let leaf = slot.terminal().expect("harness pane is a terminal");
        leaf.read(cx).host_id()
    });
    app.update(&mut vcx, |_app, cx| {
        HostLinks::set_home_for_test(cx, host, PathBuf::from("/workspace"));
    });
    let home = app.read_with(&vcx, |app, cx| {
        app.tabs[0]
            .pane
            .first_leaf()?
            .terminal()?
            .read(cx)
            .display_home(cx)
    });
    assert_eq!(
        home,
        Some(PathBuf::from("/workspace")),
        "the container's own home answers for its `~`"
    );
    assert_eq!(
        abbreviate_home("/workspace/app", home.as_deref()).as_ref(),
        "~/app",
        "a container path shortens against the container's home"
    );
}

#[gpui::test]
fn ac4_a_new_tab_in_a_container_workspace_starts_in_the_container_cwd(cx: &mut TestAppContext) {
    use std::path::PathBuf;

    let (app, mut vcx, mut streams) = harness_with_tabs(cx, 1);
    app.update(&mut vcx, |app, cx| attach_container(app, 0, "web", cx));

    let mut daemon_side = streams.remove(0);
    DaemonMsg::Cwd(PathBuf::from("/workspace/app"))
        .encode(&mut daemon_side)
        .unwrap();
    daemon_side.flush().unwrap();

    let want = PathBuf::from("/workspace/app");
    let cwd = poll_until(&want, || app.read_with(&vcx, |app, cx| pane_cwd(app, cx)));
    assert_eq!(
        cwd,
        Some(want.clone()),
        "the pane tracks the container shell"
    );

    let (start, local) = app.read_with(&vcx, |app, cx| {
        let slot = app.tabs[0]
            .pane
            .first_leaf()
            .expect("harness tab has a pane");
        let leaf = slot
            .terminal()
            .expect("harness pane is a terminal")
            .read(cx);
        (
            leaf.spawnable_cwd(),
            PaneRoute::for_workspace(leaf.workspace()).is_local(),
        )
    });
    assert_eq!(
        start,
        Some(want),
        "a new tab must start where the container shell is"
    );
    assert!(
        !local,
        "and it must ride the container route, not spawn on this machine"
    );
}
